import re
from lxml import etree
W='{http://schemas.openxmlformats.org/wordprocessingml/2006/main}'
t=etree.parse('work/un/word/document.xml')
body=t.getroot().find(W+'body')
def ptext(p):
    return ''.join(n.text or '' for n in p.iter(W+'t'))
paras=[el for el in body.iter(W+'p')]
print('num paragraphs', len(paras))
# find headings
for i,p in enumerate(paras):
    pPr=p.find(W+'pPr')
    st=None
    if pPr is not None:
        s=pPr.find(W+'pStyle')
        if s is not None: st=s.get(W+'val')
    if st and 'Heading' in st or st in ('Title',):
        print(i, st, repr(ptext(p))[:90])
EOF

